-- TPC-DS Query Query 178
-- Based on: query73.tpl (medium)
-- Variation: 1

select c_last_name ,c_first_name ,c_salutation ,c_preferred_cust_flag ,ss_ticket_number ,cnt from (select ss_ticket_number ,ss_customer_sk ,count(*) cnt from store_sales,date_dim,store,household_demographics where store_sales.ss_sold_date_sk = date_dim.d_date_sk and store_sales.ss_store_sk = store.s_store_sk and store_sales.ss_hdemo_sk = household_demographics.hd_demo_sk and date_dim.d_dom between 3 and 2 and (household_demographics.hd_buy_potential = '81' or household_demographics.hd_buy_potential = '71') and household_demographics.hd_vehicle_count > 1 and case when household_demographics.hd_vehicle_count > 1 then household_demographics.hd_dep_count/ household_demographics.hd_vehicle_count else null end > 1 and date_dim.d_year in (2086,2043,2040+3) and store.s_county in ('COUNTY_A','COUNTY_B','COUNTY_C','COUNTY_D') group by ss_ticket_number,ss_customer_sk) dj,customer where ss_customer_sk = c_customer_sk and cnt between 1 and 4 order by cnt desc, c_last_name asc;
